// Generated by scripts/embed.mjs from examples/*/smithable*.yml, examples/*/src/custom, examples/*/public and examples/*/samples. Do not edit.
export const STARTERS: Record<string, Record<string, string>> = {
  "api": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\nsignIn:\n  providers: [email]\n  selfSignUp: false\ndefaultAccess: shared\nroles:\n  admin: all\n  member:\n    description: A team member who works with the tasks and notes.\n    pages: [admin]                   # the data page; the team page is the administrators'\n    create: all\n    write: all\n    delete: all\n  assistant:\n    description: \"The AI assistant's key: reads everything, adds and changes tasks and notes, never deletes.\"\n    create: [Task, Note]\n    write: [Task, Note]\ndefaultRole: member\n# What programs and assistants reach with a key made on the team page. A key acts with its role:\n# give an assistant's key the assistant role, which reads everything, adds and changes tasks and\n# notes, and deletes nothing. Nothing is public: an assistant's memory is private.\napi:\n  models: all\n  actions: all\n  assistants: true\nadmins: [admin@team-tasks.example]\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"smithableContent: 0.1\nlogo: { src: images/logo.webp, alt: A plug, generated: true }\n","smithable.ux.yml":"smithableUx: 0.1\ntones:\n  Task.status:\n    doing: warning\n    done: success\ntheme:\n  preset: modern\n","smithable.yml":"# Tasks and notes an AI assistant keeps for a small team: an app for programs and assistants, with\n# the team page and a data page as its only screens (docs/design/api-only.md).\nsmithable: 0.1\napp:\n  name: Team Tasks\n  description: Tasks and notes, grouped in projects, that an AI assistant keeps for a small team.\n  timezone: Europe/Stockholm\nmodels:\n  Project:\n    fields:\n      name: string!\n      description: text\n      tasks: Task[]\n      notes: Note[]\n  Task:\n    fields:\n      title: string!\n      project: Project!\n      status: todo | doing | done\n      dueDate: date\n      assignee: User\n      details: text\n  Note:\n    fields:\n      title: string!\n      project: Project!\n      body: text\n      attachment: file                 # a document the note is about, sent through the API too\npages:\n  team:\n    users: manage\n  admin:\n    route: /admin\n    data: all\nactions:\n  complete:\n    on: Task\n    when:\n      status: [todo, doing]\n    set:\n      status: done\n    intent: Mark a task as done.\n  reopen:\n    on: Task\n    when:\n      status: done\n    set:\n      status: todo\n    intent: Open a finished task again.\n"},
  "barbers": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]                 # customers sign in with a code by mail, no password\n\ndefaultAccess: private               # customers see only their own appointments\n\nroles:\n  admin:\n    description: The shop. Keeps the services, the barbers and their time off; confirms appointments.\n  member:\n    description: A customer who books appointments.\n    pages: [appointments]\n    create: [Appointment]\n\nadmins: [owner@harbourcuts.example]\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home, privacy]\n  read: [Service, Barber]\n","smithable.content.yml":"# What people read. Derived from names when not given here.\nsmithableContent: 0.1\n\npages:\n  privacy:\n    title: Privacy\n    operator:\n      name: Harbour Cuts Ab\n      address: Sjögatan 4, 22100 Mariehamn\n      email: hello@harbourcuts.example\n      country: Åland, Finland\n      hosting: in the EU\n  home:\n    hero:\n      title: A good haircut, at a time that suits you\n      subtitle: Two barbers, two chairs, a short walk from the western harbour. Choose a service and a barber, then a free time. We confirm by mail, usually within the hour on a working day.\n      button: Book a time\n    services:\n      eyebrow: What we do\n      title: Services\n    barbers:\n      eyebrow: Meet the team\n      title: The barbers\n  appointments:\n    title: Appointments\n  day:\n    title: The day\n\noutgoing:\n  appointmentRequested:\n    subject: A new appointment to confirm\n    text: A customer has asked for a time. Check the barber's day and confirm it, or cancel it and call the customer if the time does not work.\n  appointmentMade:\n    subject: We have your appointment\n    text: Thank you. We have your request and mail you again when it is confirmed. You can cancel online until 12 hours before. After that, please call the shop.\n  appointmentConfirmed:\n    subject: Your appointment is confirmed\n    text: See you then. Please come a few minutes early. To cancel, sign in and open the appointment; within 12 hours of the time, call the shop instead.\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: modern\n\ntones:\n  Appointment.status: { requested: warning, confirmed: success, cancelled: neutral }\n\npages:\n  home:\n    sections:\n      services: { layout: ledger }     # the price list as ruled rows, the prices in a column\n      barbers: { band: muted }         # the team on the muted band, apart from the price list\n  appointments:\n    table:\n      columns: [startsAt, service, barber, name, status]\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Harbour Cuts\n  description: Appointments with a small barbershop's barbers, booked online by their time.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  Service:\n    description: What a customer books, such as a haircut or a beard trim, with how long it takes.\n    fields:\n      name: string!\n      summary: text\n      minutes: int! = 30\n      price: money\n\n  Barber:\n    description: One of the barbers whose time customers book.\n    fields:\n      name: string!\n      bio: text\n      portrait: picture\n      timeOffs: TimeOff[]               # their days off, on their page\n    schedule:                           # the shop's week; a barber's days off are Time off\n      hours: { mon-fri: \"09:00-17:00\", sat: \"10:00-14:00\" }\n      breaks: \"12:00-12:30\"\n      gap: 10                           # minutes to sweep up after each appointment\n      away: TimeOff\n\n  TimeOff:\n    description: Days or hours a barber is away, such as a holiday, a course or a dentist's appointment.\n    fields:\n      barber: Barber!\n      from: datetime!\n      until: datetime!\n      note: string\n\n  Appointment:\n    description: A customer's appointment with a barber for a service.\n    fields:\n      service: Service!\n      barber: Barber!\n      startsAt: datetime!\n      name: string!\n      phone: phone\n      note: text\n      status: { type: requested | confirmed | cancelled, by: app }\n    occupies:                           # an appointment takes its barber's time, never two at once\n      resource: barber\n      starts: startsAt\n      duration: service.minutes\n      while: { status: [requested, confirmed] }\n      cancelUntil: 12h                  # the customer cancels online until 12 hours before\n\nactions:\n  confirm:\n    on: Appointment\n    when: { status: requested }\n    set: { status: confirmed }\n  cancel:\n    on: Appointment\n    when: { status: [requested, confirmed] }\n    set: { status: cancelled }\n\noutgoing:\n  appointmentRequested:\n    when: Appointment created\n    to: mail\n    recipient: admin                    # the shop hears of each new request\n  appointmentMade:\n    when: Appointment created\n    to: mail\n    recipient: owner                    # the customer who booked\n  appointmentConfirmed:\n    when: confirm\n    to: mail\n    recipient: owner\n\npages:\n  home:\n    route: /\n    landing:\n      hero: { button: appointments }\n      services: { records: Service }\n      barbers: { records: Barber }\n      footer:\n  appointments:                         # a customer's own; the shop's all, with Confirm and Cancel\n    crud: Appointment\n    actions: [confirm, cancel]\n    filters: [status]\n  day:                                  # the shop's day, a column per barber\n    calendar: { model: Appointment, starts: startsAt, duration: service.minutes, title: name }\n  services:\n    crud: Service\n  barbers:\n    crud: Barber\n  time-off:\n    crud: TimeOff\n  privacy:\n    route: /privacy\n    legal: privacy\n"},
  "booking": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]\n\ndefaultAccess: private             # members only see their own records\n\nroles:                             # what each role may do, beyond their own records\n  admin:\n    description: Studio staff. Manage the schedule, classes and teachers.\n  member:\n    description: A student who books classes.\n    pages: [my-bookings]             # the public pages are open to everyone\n    create: [Booking]                # members book; the classes and sessions are the staff's\n\nadmins: [owner@stillwater.example]\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home, schedule, blog, about, privacy]    # the landing page, the schedule, the blog, about us, the privacy page\n  read:\n    - ClassType\n    - Instructor\n    - Session\n    - Post: { where: { status: published } }   # visitors read published posts, not drafts\n  create: [Message]                # the contact form; only admins read the messages\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"# What visitors read. Derived from names when not given here.\nsmithableContent: 0.1\nlogo: { src: images/logo.webp, alt: A lotus over a ripple, generated: true }\n\nmodels:\n  ClassType:\n    fields:\n      level: { values: { allLevels: All levels } }\n  Booking:\n    reserve: { book: Book a mat, cancel: Cancel booking, full: No mats left }\n\noutgoing:\n  bookingMade:\n    subject: \"Your booking: {session}\"\n    text: Thank you for booking. We look forward to seeing you. Please come ten minutes early to settle in; mats, blocks and blankets are by the door. If you cannot come after all, cancel the booking before the class starts so the mat goes to someone else.\n  bookingChanged:\n    subject: Your booking was changed\n    text: The studio changed your booking. Here it is as it is now. If the new class does not suit you, cancel it before it starts, or write to us and we will find you another.\n  bookingCancelled:\n    subject: Your booking was cancelled\n    text: Your booking was cancelled. Here it is as it was. If this was a mistake, book the class again from the schedule while mats are left, or write to us.\n  sessionMoved:\n    subject: Your class has a new time\n    text: \"{by} moved {classType}, a class you booked, from {before.startsAt} to {startsAt}. Your mat is kept for you. If the new time does not suit you, cancel the booking so the mat goes to someone else.\"\n\nmenus:\n  schedule: { label: Schedule }\n  messages: { label: Messages }\n  studioSetup: { label: Studio setup }\n  website: { label: Website }\n  admin: { label: Administration }\n\npages:\n  privacy:\n    title: Privacy\n    operator:\n      name: Calm Yoga Studio Ab\n      address: Torggatan 1, 22100 Mariehamn\n      email: hello@calmyoga.example\n      country: Åland, Finland\n      hosting: in the EU\n  about:\n    title: About us\n    story:\n      title: A small studio by the harbour\n      text: |-\n        Stillwater began in 2019 as one evening class a week in a borrowed room above a bakery. Today it is a studio of\n        its own on Storagatan, a few minutes from the harbour, with classes from seven in the morning to late evening.\n\n        The classes stay small, never more than sixteen mats, so every teacher knows your name and how your practice\n        is going. The room has wooden floors, tall windows and a radiator under each of them, which matters in February.\n\n        We keep things simple. You book a mat online, you cancel it if plans change, and if you want to talk about\n        your practice, there is time for that after class.\n    team: { title: Who teaches }\n    faq:\n      title: Questions before you come\n      items:\n        - question: Do I need experience?\n          answer: No. Foundations and all-levels classes are made for beginners, and every posture has an easier version.\n        - question: How early should I arrive?\n          answer: Ten minutes before the class, to settle in and find your mat. We close the door when the class starts, to keep the room quiet.\n        - question: Which languages do the teachers speak?\n          answer: All classes are taught in Swedish and English. Aino also teaches in Finnish if you ask.\n        - question: Is there a changing room?\n          answer: Yes, with lockers and two showers. Bring a padlock or borrow one at the desk.\n        - question: Can I buy a gift card?\n          answer: Yes, for one class or for a month. Ask at the desk or write to us, and we will post it or keep it for you to collect.\n  home:\n    description: Small yoga classes in Mariehamn for every level, from a first class to arm balances. See the schedule and book a mat online.\n    estimate:\n      title: Would a monthly pass pay off?\n      text: Try your own numbers. One class is 16 euros and the monthly pass 99, so at seven classes a month or more the pass is cheaper. Nothing you type is saved.\n      fields:\n        classesPerMonth: { label: Classes a month }\n        dropIn: { label: One class }\n        pass: { label: Monthly pass }\n        withoutPass: { label: Paying per class }\n        saved: { label: The pass saves you }\n      results: A month\n    hero:\n      title: Find your calm\n      subtitle: Small yoga classes for every level, a short walk from the harbour in Mariehamn. Book a mat online and come as you are.\n      button: See the schedule\n      secondButton: Read the blog\n      image:\n        src: images/hero.webp\n        alt: People stretching on yoga mats in a bright studio with large windows\n        generated: true\n    classes:\n      eyebrow: Small groups\n      title: Our classes\n      text: Six kinds of class, from first steps to deep stretches and arm balances. Each has an easier version of every posture, so you can start where you are.\n    faq:\n      eyebrow: New here?\n      title: Before your first class\n      items:\n        - question: Do I need experience?\n          answer: No. Foundations and all-levels classes are made for beginners. The teacher shows the easier version of each posture first.\n        - question: What should I bring?\n          answer: Comfortable clothes and water. Mats, blocks, straps and blankets are here for you, free of charge.\n        - question: How do I cancel a booking?\n          answer: Open it under My bookings and cancel it before the class starts. The mat then goes to someone else.\n        - question: What does a class cost?\n          answer: One class is 16 euros. A monthly pass is 99 euros and covers as many classes as you like that month.\n        - question: Can I come if I am pregnant or have an injury?\n          answer: Often yes. Write to us or tell the teacher before the class, and we will suggest the classes that suit you.\n    callToAction:\n      title: Your first class is waiting\n      button: Book a class\n    gallery:\n      eyebrow: The studio\n      title: Inside the studio\n      items:\n        - image: { src: images/gallery/studio.webp, alt: A rolled-up yoga mat and a water bottle on a wooden floor by a window, generated: true }\n          caption: Morning light in the studio\n        - image: { src: images/gallery/class.webp, alt: Three people stretching sideways in a bright room, generated: true }\n          caption: Our Tuesday evening class\n        - image: { src: images/gallery/coast.webp, alt: A runner on a path by the sea at sunset, generated: true }\n          caption: Summer sessions by the sea\n    contact:\n      title: Questions? Write to us\n      text: We answer within a day, usually the same evening. If you need to change a booking for today, call the desk instead.\n      address: |\n        Storagatan 1\n        22100 Mariehamn\n      phone: +358 18 123 456\n      email: hello@stillwater.example\n      hours: |\n        Monday to Friday 7–21\n        Saturday and Sunday 9–19\n      button: Send message\n      thanks: Thank you! We will get back to you within a day.\n    footer:\n      text: Stillwater Yoga · Storagatan 1, Mariehamn\n      items:\n        - { label: Class schedule, link: /schedule }\n        - { label: Email us, link: \"mailto:hello@stillwater.example\" }\n  schedule:\n    title: Class schedule\n    subtitle: This week's and next week's classes. Choose one to see how many mats are left and book yours.\n  my-bookings:\n    cancelling:\n      title: Can't come after all?\n      text: Open the booking and cancel it before the class starts, so the mat goes to someone else. Once the class has started it can no longer be cancelled here; call the desk and we will sort it out.\n  sessions:\n    title: Sessions\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: stillwater                   # the studio's own theme: one ink on warm paper\n\npages:\n  home:\n    sections:\n      hero: { layout: inset, facts: [Instructor, ClassType], eyebrow: address }   # the picture as a tall card, the teachers and classes counted, the city over the title\n      classes: { layout: cards }\n      estimate: { band: muted }        # every second section on the muted band, as a club's site\n      faq: { layout: accordion, band: muted }\n      callToAction: { band: primary }\n      contact: { band: muted }\n  # The members' pages in the site frame, for staff too (page-sections.md §4).\n  schedule:\n    frame: site\n    # Each class coloured by its level, its places a dot each (look-gap §4).\n    calendar: { colorBy: classType.level, capacity: { left: placesLeft, of: capacity, look: pips } }\n  my-bookings: { frame: site }\n  about: { frame: site }\n  sessions:\n    filters: { shown: [startsAt, classType], look: chips }   # the instructor behind \"More filters\"; every value a chip, an instructor's with their portrait\n    # Under a session's name where there is room: who teaches it, and its level.\n    record: { subtitle: instructor.name, detail: [classType.level] }\n    table:\n      columns: [classType, startsAt, instructor, placesLeft, capacity]\n      sort: startsAt\n    form:\n      fieldOrder: [classType, instructor, startsAt, capacity]\n      columns: 2\n      control: { classType: select, instructor: select, capacity: stepper }\n  class-types:\n    table: { view: cards, sort: name }\n  instructors:\n    table: { columns: [name, portrait], view: cards }\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Stillwater Yoga\n  description: Class schedule and online booking for a small yoga studio.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  ClassType:\n    description: A kind of class the studio offers, such as Vinyasa, Yin, Hatha or Foundations.\n    fields:\n      name: string!\n      summary: text\n      level:                            # long form: default is not the first value\n        type: beginner | allLevels | advanced\n        default: allLevels\n      durationMinutes: int! = 60\n      sessions: Session[]               # the sessions of this kind, on its page\n\n  Instructor:\n    fields:\n      name: string!\n      bio: markdown                     # formatted text: headings, lists, links\n      portrait: picture                 # a stored picture with its description\n      sessions: Session[]               # the classes they teach, on their page\n\n  Session:\n    description: One scheduled occurrence of a class.\n    namedBy: [classType, startsAt]     # \"Hatha · Mon 19 Oct, 08:00\"\n    fields:\n      classType: ClassType!\n      instructor: Instructor!\n      startsAt: datetime!\n      capacity: int! = 12\n      bookings: Booking[]\n      placesLeft: { type: int, formula: capacity - COUNT(bookings) }\n\n  Booking:\n    description: A member's place in a session.\n    namedBy: session                   # named as its session is\n    fields:\n      session: Session!  unique         # private access: one booking per member and session\n      attendee: User                    # whose place it is: staff book for a member, a member for themselves\n    ownedBy: attendee                   # left empty, the one who books; only staff may choose someone else\n    capacity:                           # a session never has more bookings than its capacity\n      per: session\n      max: session.capacity\n      closes: session.startsAt          # booking until the class starts\n      cancelUntil: session.startsAt     # and cancelling (e.g. \"2 hours before session.startsAt\")\n\n  Post:\n    description: News and articles on the studio's blog.\n    fields:\n      title: string!\n      address: string unique            # the article's address; made from the title when empty\n      summary: text\n      cover: picture\n      body: markdown!\n      publishedOn: date\n      status: draft | published\n\n  Message:\n    description: A question a visitor sends from the contact form on the home page.\n    fields:\n      name: string!\n      email: email!\n      message: text!\n\nactions:\n  publish:\n    on: Post\n    when: { status: draft }\n    set: { status: published }\n    intent: The post is out for everyone to read.\n\n# What the app does on a clock: a reminder the day before, and a post out on its date.\ntimers:\n  remind:\n    on: Booking\n    at: 1 day before session.startsAt   # raises its event; the reminder below mails it\n  publish:\n    on: Post\n    at: publishedOn\n    where: { status: draft }\n    run: publish\n\noutgoing:\n  reminder:\n    when: remind\n    to: mail\n    recipient: owner\n  bookingMade:\n    when: Booking created\n    to: mail\n    recipient: owner                 # the member who booked\n  bookingChanged:\n    when: Booking changed\n    to: mail\n    recipient: owner                 # when the studio moves it; not for the member's own edit\n  bookingCancelled:\n    when: Booking deleted\n    to: mail\n    recipient: owner\n  sessionMoved:\n    when: Session changed\n    fields: [startsAt]                # only a new time counts\n    show: [classType, startsAt, instructor]   # the mail lists these, not the capacity\n    previous: true                    # and says what the time was\n    to: mail\n    recipient: bookings.owner        # one mail per booking, to the member who booked\n\npages:\n  home:\n    route: /\n    landing:\n      hero: { button: schedule, secondButton: blog }\n      classes: { records: ClassType }\n      estimate:                         # does a monthly pass pay off? Worked out as you type\n        calculator:\n          fields:\n            classesPerMonth: { type: int, min: 0, max: 31, default: 8 }\n            dropIn: { type: money, min: 0, default: 16 }\n            pass: { type: money, min: 0, default: 99 }\n            withoutPass: { type: money, formula: classesPerMonth * dropIn }\n            saved: { type: money, formula: classesPerMonth * dropIn - pass }\n          examples:\n            - input: { classesPerMonth: 8, dropIn: 16, pass: 99 }\n              expected: { withoutPass: 128, saved: 29 }\n      gallery:\n      faq:\n      callToAction: { button: schedule }\n      news: { records: Post }\n      contact: { form: Message }\n      footer:\n  schedule:                           # the week's classes, for visitors too\n    calendar: { model: Session, duration: classType.durationMinutes }\n  sessions:                           # the staff's list of sessions\n    crud: Session\n    filters: [classType, instructor, startsAt]\n    defaultFilter: { startsAt: upcoming }   # opens on what is to come; All shows the past too\n    sortable: [startsAt, capacity]\n  class-types:\n    crud: ClassType\n    filters: [level]\n  instructors:\n    crud: Instructor\n  messages:\n    crud: Message\n  blog:                               # the studio's articles, for visitors too\n    articles: Post\n  about:                              # a page of parts: the story, who teaches, questions\n    sections:\n      story: { text: }\n      team: { records: Instructor }\n      faq:\n  privacy:\n    route: /privacy\n    legal: privacy                      # written from the app: who runs it, what it stores, cookies, mail\n  posts:                              # where staff write them\n    crud: Post\n    filters: [status]\n  my-bookings:                        # a member's own bookings (private access)\n    crud: Booking\n    sections:\n      cancelling: { text: }             # a note under the list\n  admin:\n    data: all                      # every model, for administrators\n\n# The menus: what members use first, then the studio's setup and its website. A page in no menu\n# is in none, so every page people open is named here.\nnavigation:\n  schedule: [schedule, my-bookings, sessions]\n  messages: [messages]\n  studioSetup: [class-types, instructors]\n  website: [blog, about, posts, home]\n  admin: [admin]\n"},
  "crm": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]\n  allowedDomains: [acme.example]   # only Acme's addresses\n  selfSignUp: false                # and only colleagues invited from the team page\n\ndefaultAccess: shared              # an internal tool: colleagues see each other's data\n\nroles:                             # what each role may do, beyond their own records\n  admin: all\n  sales:\n    description: Works with customers and orders.\n    pages: all                       # every page but the team page, which is the administrators'\n    create: all\n    write: all                       # anyone's customers and orders; deleting them stays each one's own, and admins'\n\n\nadmins: [owner@acme.example]           # become admin when they sign in\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: []                        # an internal tool: nothing is public\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"# Visible text. Only what differs from the texts Smithable derives from names.\nsmithableContent: 0.1\nlogo: { src: images/logo.webp, alt: Two interlinked rings, generated: true }\n\nmodels:\n  Customer:\n    fields:\n      segment:\n        values: { smb: Small business }\n      creditLimit:\n        help: Orders are held when the outstanding balance goes above this amount. Agree a higher limit with the customer before you change it.\n  Order:\n    fields:\n      placedAt: { label: Placed on }\n\npages:\n  start:\n    title: Overview\n    subtitle: What needs you today.\n    openOrders: { label: Open orders }\n    followUpsDue: { label: Follow-ups due }\n    recent: { label: Latest changes }\n  customers: { subtitle: Keep every relationship in view. }\n  orders: { subtitle: Every order and where it stands. }\n  team: { subtitle: Who has access and who is invited. }\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: workbench         # the CRM's own theme: compact, quiet, a light sidebar\n\npages:\n  customers:\n    table:\n      columns: [name, email, segment, creditLimit]\n      below: { email: phone }   # the phone number under the email\n      sort: name\n      mark: initials            # each customer's initials before their name\n    form:\n      sections:                 # groups with headings; their texts are in the content file\n        - { name: contact, fields: [name, email, phone] }\n        - { name: terms, fields: [segment, creditLimit, accountManager] }\n        - { name: notes, fields: [notes] }\n      columns: 2\n      control: { notes: textarea }\n\ntones:\n  Order.status: { shipped: success, canceled: danger }\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Acme CRM\n  description: Lightweight CRM for a small B2B sales team.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  Customer:\n    description: A company we have a commercial relationship with.\n    trash: true                       # a deleted customer can be restored for thirty days\n    fields:\n      name: string!\n      email: email unique\n      phone: phone\n      segment: smb | enterprise | government      # first value is the default\n      creditLimit:\n        type: money\n        min: 0\n        description: Maximum outstanding balance before new orders are held.\n      notes: text\n      accountManager: User\n      orders: Order[]                # every order that refers to this customer\n      followUps: FollowUp[]          # what to do next with them, and when\n    ownedBy: accountManager          # the account manager owns the customer\n\n  Order:\n    trash: true\n    fields:\n      number: string! unique\n      customer: Customer!\n      status: draft | placed | shipped | canceled\n      total: money!\n      shippingMethod: standard | express\n      shippingCost:\n        type: money\n        formula: IF(AND(shippingMethod = \"standard\", total > 100), 0, IF(shippingMethod = \"express\", 15, 5))\n        description: Standard shipping is free above 100 EUR, otherwise 5 EUR. Express always costs 15 EUR.\n        examples:\n          - input: { total: 150, shippingMethod: standard }\n            expected: 0\n          - input: { total: 80, shippingMethod: standard }\n            expected: 5\n          - input: { total: 150, shippingMethod: express }\n            expected: 15\n      placedAt: datetime = NOW()\n\n  FollowUp:\n    trash: true\n    fields:\n      customer: Customer!\n      dueOn: date! = TODAY()\n      done: bool\n      note: text\n\nactions:\n  mergeCustomers:\n    merge: Customer                  # two customers become one: orders and follow-ups move to the kept one\n  scheduleFollowUps:\n    custom: true\n    input: { customer: Customer!, count: int!, everyDays: int! }\n    output: { created: int! }\n    intent: Plan a series of follow-up notes for a customer, one every so many days.\n    rules:\n      - The first note is due today; each next one everyDays later.\n\npages:\n  customers:\n    intent: Find a customer quickly and keep their details current.\n    crud: Customer\n    search: [name, email]\n    actions: [mergeCustomers, scheduleFollowUps]\n  orders:\n    crud: Order\n    search: [number, customer]\n    filters: [status]\n  followUps:\n    crud: FollowUp\n    search: [customer, note]\n    filters: [done]\n  team:\n    intent: Invite colleagues and manage who has access.\n    users: manage\n  start:                             # the start page: what needs you today (look-gap §4)\n    route: /\n    dashboard:\n      customers: { count: Customer }\n      openOrders: { count: Order, where: { status: [draft, placed] } }\n      followUpsDue: { list: FollowUp, when: dueOn, within: 2 weeks, where: { done: false } }   # the overdue first, marked\n      recent: { activity: changes }  # the latest changes, for administrators\n\nnavigation: [start, customers, orders, followUps, team]\n"},
  "invoicing": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]\n\ndefaultAccess: private             # each freelancer sees only their own data\n\nroles:\n  admin: all\n  member: { description: A freelancer using Invoicely., pages: all, create: all }\n\nadmins: [owner@invoicely.example]\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home]                    # the landing page\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"# What visitors read. Derived from names when not given here.\nsmithableContent: 0.1\nlogo: { src: images/logo.webp, alt: A receipt with a torn edge and a coin, generated: true }\n\nmodels:\n  BusinessProfile:\n    fields:\n      vatNumber: { label: VAT number }\n      iban: { label: IBAN, help: Where clients pay your invoices. It is printed on every invoice. }\n      paymentTermDays: { label: Days to pay }\n  Client:\n    fields:\n      vatNumber: { label: VAT number }\n\noutgoing:\n  invoiceSent:\n    subject: Your invoice\n    text: Here is your invoice. The due date, the amount and the account to pay to are on it. If anything looks wrong, reply to this mail and I will sort it out. Thank you for your business.\n\npages:\n  home:\n    hero:\n      title: Get paid for your work, without the paperwork\n      subtitle: Invoicely keeps your clients, invoices and payments in one place, so you always know who owes you what. It is made for one person doing good work, not for an accounts department.\n      button: Start invoicing\n      image:\n        src: images/hero.webp\n        alt: A calculator, receipts and a laptop on a wooden desk\n        generated: true\n    features:\n      eyebrow: Why Invoicely\n      title: Everything a freelancer needs\n      items:\n        - title: Invoices in a minute\n          text: Add the lines with hours or pieces and a price, and the total works itself out. The due date follows from the issue date.\n        - title: See what is overdue\n          text: Every invoice shows whether it is a draft, sent, paid or overdue. A sent invoice turns overdue on its own a week after its due date.\n        - title: Your clients in one place\n          text: Addresses, mail addresses and VAT numbers are there when you need them, with every invoice you have sent each client.\n        - title: The contract with the invoice\n          text: Attach the agreement as a PDF, so the work and the bill stay together when a client asks.\n    pricing:\n      eyebrow: Pricing\n      title: Simple pricing\n      text: Example plans; the prices are illustrative.\n      items:\n        - name: Free\n          price: €0\n          period: per month\n          features: [Up to 5 clients, Unlimited invoices]\n          button: Start for free\n        - name: Pro\n          price: €9\n          period: per month\n          features: [Unlimited clients, Reminders for overdue invoices, Priority support]\n          button: Try Pro\n    faq:\n      eyebrow: Good to know\n      title: Questions\n      items:\n        - question: Can I use my own invoice numbers?\n          answer: Yes. Numbers are yours to choose. Most people count per year, like 2026-001, 2026-002.\n        - question: Who can see my invoices?\n          answer: Only you. Each freelancer sees their own clients and invoices, and nobody else's.\n        - question: Can I change an invoice after sending it?\n          answer: A sent or paid invoice is not edited; you credit it instead. A draft you can change as often as you like.\n        - question: What happens when a client pays late?\n          answer: A week after the due date a sent invoice is marked overdue, and the overview shows how much is late in total.\n        - question: Can I start a new invoice from an old one?\n          answer: Yes. Duplicate an invoice and its lines come along. Give the copy its own number and change what differs.\n    callToAction:\n      title: Send your next invoice with Invoicely\n      button: Get started\n  overview:\n    subtitle: Who owes you what, at a glance. Sent, overdue and paid, and what you invoiced each month.\n    outstanding: { label: Outstanding }\n    invoiced: { label: Invoiced by month }\n    latest: { label: Latest invoices }\n  invoices: { subtitle: Every invoice and where it stands. Mark one sent when it goes out and paid when the money is in. }\n  clients: { subtitle: \"The people and companies you work for, with the details your invoices need.\" }\n  settings:\n    subtitle: Your business details, as your invoices show them. Changes apply to invoices you send from now on.\n  welcome:\n    subtitle: A little setup now, and your invoices are ready to send. You can change all of it later in settings.\n    business: { title: Your business }\n    payment:\n      title: Getting paid\n      text: Clients see these on every invoice. Most clients expect 14 or 30 days to pay.\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: modern\n\n# Status colors by meaning; values not listed are neutral.\ntones:\n  Invoice.status: { paid: success, overdue: warning }\n\npages:\n  home:\n    theme: { brand: { font: Outfit } }   # the public page in a rounder face than the tool behind it\n    sections:                          # how the landing page's sections look\n      hero: { layout: centered }       # the text over the picture\n      pricing: { highlight: Pro }      # the plan drawn forward\n      faq: { layout: list, columns: 2 }   # every answer shown, two abreast\n      callToAction: { band: primary }  # the one band on an otherwise open page\n  invoices:\n    table:\n      columns: [number, client, status, issuedOn, total]\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Invoicely\n  description: Simple invoicing for freelancers. Each user manages their own clients and invoices.\n  currency: EUR\n\nmodels:\n  BusinessProfile:\n    description: The freelancer's own business details, printed on their invoices.\n    fields:\n      businessName: string!\n      vatNumber: string\n      iban: string\n      paymentTermDays: int! = 30\n      invoiceFooter: text\n\n  Client:\n    fields:\n      name: string!\n      email: email!\n      address: text\n      vatNumber: string\n      invoices: Invoice[]\n\n  Invoice:\n    fields:\n      number: string! unique\n      client: Client!\n      issuedOn: date! = TODAY()\n      dueOn:\n        type: date!\n        default: DATEADD(issuedOn, 30, \"day\")\n      status: draft | sent | paid | overdue\n      contract: file                   # the agreement the invoice is for, as a PDF or a document\n      lines: InvoiceLine[]\n      total:\n        type: money\n        formula: SUM(lines.amount)\n    rules:\n      - Invoice numbers are sequential per user, like 2026-001, 2026-002.\n      - A sent or paid invoice can no longer be edited, only credited.\n\n  InvoiceLine:\n    fields:\n      invoice: Invoice!\n      description: string!\n      quantity: decimal! = 1\n      unitPrice: money!\n      amount:\n        type: money\n        formula: quantity * unitPrice\n        examples:\n          - input: { quantity: 3, unitPrice: 40 }\n            expected: 120\n          - input: { quantity: 0.5, unitPrice: 19.99 }\n            expected: 10\n\nactions:\n  markSent:\n    on: Invoice\n    when: { status: draft }\n    set: { status: sent }\n    intent: The invoice went to the client.\n  markPaid:\n    on: Invoice\n    when: { status: [sent, overdue] }\n    set: { status: paid }\n    intent: The client paid the invoice.\n  markOverdue:\n    on: Invoice\n    when: { status: sent }\n    set: { status: overdue }\n    intent: The invoice is late.\n\n# What the app does on a clock: a week after its due date, a sent invoice is overdue.\ntimers:\n  markOverdue:\n    on: Invoice\n    at: 7 days after dueOn\n    where: { status: sent }\n    run: markOverdue\n\noutgoing:\n  invoiceSent:\n    when: markSent                   # an action: when it has run\n    to: mail\n    recipient: client.email\n\npages:\n  home:\n    route: /\n    landing:\n      hero: { button: overview }\n      features:\n      pricing:\n      faq:\n      callToAction: { button: overview }\n  overview:\n    dashboard:\n      outstanding: { sum: Invoice.total, where: { status: sent } }\n      overdue: { sum: Invoice.total, where: { status: overdue } }\n      paid: { sum: Invoice.total, where: { status: paid } }\n      invoiced: { sum: Invoice.total, by: issuedOn }\n      latest: { list: Invoice, limit: 5 }\n  invoices:\n    crud: Invoice\n    filters: [client, status]\n    actions: [markSent, markPaid]\n  clients:\n    crud: Client\n  invoice-lines:\n    crud: InvoiceLine\n  settings:\n    settings: BusinessProfile\n  welcome:\n    onboarding:\n      model: BusinessProfile\n      steps:\n        business: [businessName, vatNumber]\n        payment: [iban, paymentTermDays]\n"},
  "kiosk": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]\n  selfSignUp: false                # only staff invited from the team page\n\ndefaultAccess: shared              # everyone on the staff sees every order\n\nroles:\n  admin: all\n  staff:\n    description: Takes the orders and keeps the menu.\n    pages: [orders, dishes, stops]\n    create: all\n    write: all\n    actions: all\n\ndefaultRole: staff\nadmins: [owner@kiosken.example]\n\n# The menu and where the truck stands are open to everyone; visitors send orders without an account.\npublic:\n  pages: [menu, where]\n  read: [Dish, Stop]\n  create: [Order]\n","smithable.content.yml":"# What people read. Derived from names when not given here.\nsmithableContent: 0.1\nlogo: { src: images/logo.webp, alt: A cup, generated: true }\n\nmodels:\n  Dish:\n    fields:\n      section: { values: { starters: Starters, mains: Mains, drinks: Drinks, sweets: Sweets } }\n\npages:\n  menu:\n    title: Order from the truck\n  where:\n    title: Where we are\n    hero:\n      title: Find the truck\n      subtitle: Fish soup, salmon, burgers and cinnamon buns from a small truck that moves around Mariehamn during the week. Order ahead on the menu, tell us when you come, and pick up at the hatch. Or just walk up and order there.\n      image:\n        src: images/hero.webp\n        alt: People at tables under string lights by a food truck on a summer evening\n        generated: false\n    stops:\n      title: This week\n\noutgoing:\n  orderPlaced:\n    subject: A new order\n    text: A new order has come in. Open the orders page to accept it, or decline it and say why.\n  orderAccepted:\n    subject: Your order is being made\n    text: Thank you. The kitchen has your order and has started on it. We mail you again when it is ready at the hatch.\n  orderReady:\n    subject: Your order is ready\n    text: Your order waits at the hatch. Tell us your order number when you come. We keep hot food warm for about fifteen minutes.\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: street-food\n  brand: { primary: \"#b0402f\", background: \"#e8a33d\" }   # the red a notch quieter; the string lights' amber: cream in light, a warm deep brown in dark\n\ntones:\n  Order.status: { new: warning, accepted: neutral, ready: success, collected: neutral, declined: danger }\n\npages:\n  where:\n    sections:\n      hero: { layout: photo }          # the evening by the truck across the window, the text on a dark scrim\n      stops: { band: muted }           # the week's stops apart from the hero; the cards read better than on the red\n  orders:\n    table:\n      columns: [number, name, status, wanted, total]\n","smithable.yml":"smithable: 0.1\napp:\n  name: Kiosken\n  description: A harbour food truck where people order ahead and pick up.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  Dish:\n    fields:\n      name: string!\n      description: text\n      price: money!\n      section: starters | mains | drinks | sweets\n      picture: picture\n      diet: none | vegetarian | vegan\n      allergens: string                        # free text: \"fish, gluten\"\n      available: bool = true\n  Order:\n    fields:\n      number: { type: int!, sequence: true }   # given by the app, counting up, said to the customer\n      name: string!\n      phone: phone!\n      email: email\n      wanted: datetime                         # empty means as soon as possible\n      note: text\n      status: new | accepted | ready | collected | declined\n      reason: text\n      lines: OrderLine[]\n      total: { type: money, formula: SUM(lines.amount) }\n  OrderLine:\n    fields:\n      order: Order!\n      dish: Dish!\n      quantity: int! = 1\n      unitPrice: money!                        # the dish's price when ordered\n      amount: { type: money, formula: quantity * unitPrice }\n  Stop:                                        # where the truck stands when\n    fields:\n      place: string!\n      day: date!\n      hours: string!                           # as written: \"11:00-14:00\"\n      note: text\n\npages:\n  menu:\n    route: /\n    order:\n      from: Dish\n      into: Order\n      ask: [name, phone, email, wanted, note]\n      hours: { mon-thu: \"11:00-20:00\", fri-sat: \"11:00-22:00\" }\n      lead: 20\n  orders:\n    crud: Order\n    filters: [status]\n    sortable: [createdAt, wanted]\n    actions: [accept, ready, collected, decline]\n  dishes:\n    crud: Dish\n    filters: [section, available]\n    actions: [soldOut, backOn]\n  stops:\n    crud: Stop\n  where:\n    landing:\n      hero: {}\n      stops: { records: Stop, limit: 7 }\n      footer: {}\n  team:\n    users: manage\n\nnavigation: [orders, dishes, stops, team]\n\nactions:\n  soldOut:\n    on: Dish\n    when: { available: true }\n    set: { available: false }\n    intent: Nothing more of it today.\n  backOn:\n    on: Dish\n    when: { available: false }\n    set: { available: true }\n    intent: It can be ordered again.\n  accept:\n    on: Order\n    when: { status: new }\n    set: { status: accepted }\n    intent: The kitchen takes the order.\n  ready:\n    on: Order\n    when: { status: accepted }\n    set: { status: ready }\n    intent: The order waits at the hatch.\n  collected:\n    on: Order\n    when: { status: ready }\n    set: { status: collected }\n    intent: The customer has it.\n  decline:\n    on: Order\n    when: { status: [new, accepted] }\n    set: { status: declined, reason: }\n    intent: \"The order cannot be made: say why.\"\n\noutgoing:\n  orderPlaced:   { when: Order created, to: mail, recipient: admin }\n  orderAccepted: { when: accept, to: mail, recipient: email }\n  orderReady:    { when: ready, to: mail, recipient: email }\n  toKitchen:     { when: Order created, to: kitchen }   # OUTGOING_KITCHEN_URL and _SECRET\n"},
  "marketplace": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]              # anyone may sign up and sell\n\ndefaultAccess: private             # people change only their own items\n\nroles:\n  admin: all\n  member: { description: Sells and saves items., pages: all, create: all }\n\ndefaultRole: member\nadmins: [owner@torget.example]\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home, catalog]         # the catalog is the front door\n  read: [Item]                     # items, never who sells them: the owner is not shown\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"# What visitors read. Derived from names when not given here.\nsmithableContent: 0.1\nlogo: { src: images/logo.webp, alt: A price tag, generated: true }\n\nmodels:\n  Item:\n    label: Item\n    fields:\n      category: { values: { bikes: Bikes, kids: Kids' things } }\n      condition: { values: { likeNew: Like new, good: Good, worn: Well used } }\n      place: { label: Where }\n\npages:\n  catalog:\n    title: For sale\n    subtitle: Second-hand things from people nearby.\n  myItems:\n    title: My items\n  saved:\n    title: Saved\n  home:\n    hero:\n      title: Give things a second home\n      subtitle: Sell what you no longer use, and find what you need, from people nearby.\n      button: Browse items\n      secondButton: Sell something\n      image:\n        src: images/hero.webp\n        alt: An outdoor market with stalls of vegetables and flowers\n        generated: true\n    latest:\n      eyebrow: Near you\n      title: Like new\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: modern\n\npages:\n  home:\n    sections:\n      hero: { layout: stage, stage: catalog }   # the catalog itself beside the headline (look-breadth §3)\n      latest: { layout: grid, columns: 4, band: muted }   # the like-new items' pictures, a row of four\n  catalog:\n    table: { view: cards }\n","smithable.yml":"# Torget: a local marketplace. People sell things they no longer need; visitors browse.\nsmithable: 0.1\n\napp:\n  name: Torget\n  description: Buy and sell second-hand things in your neighborhood.\n  currency: EUR\n\nmodels:\n  Item:\n    fields:\n      title: string!\n      photos: pictures!             # an item without a photo is not a listing\n      description: text!\n      price: money\n      category: furniture | bikes | electronics | sports | kids | other\n      condition: likeNew | good | worn\n      place: string\n      available: bool = true\n    review: [photos]               # required, so an item waits for its photos to be approved\n\npages:\n  home:\n    route: /welcome\n    landing:\n      hero: { button: catalog, secondButton: myItems }\n      latest: { records: Item, search: true, filters: [category], where: { condition: likeNew }, limit: 4 }   # a slice of its own beside the stage\n      footer: {}\n  catalog:\n    route: /\n    crud: Item\n    search: [title, description, place]\n    filters: [category, price, condition, available]\n    sortable: [price, createdAt]\n    favorites: true\n    contact: owner\n  myItems:\n    crud: Item\n    mine: true\n  saved:\n    crud: Item\n    favorites: only\n  review:\n    review: all                    # for admins: the photos waiting for approval\n\nnavigation:\n  main: [catalog, myItems, saved, review]\n"},
  "records": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]\n\ndefaultAccess: private             # the collection itself is public (below); private covers the rest\n\nroles:\n  admin: all\n  member: { description: Looks at it. }   # the collection is public; only administrators add to it\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home, items]             # the collection is a public site\n  read: [Item]\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"smithableContent: 0.1\nlogo: { src: images/logo.webp, alt: Three stacked cards, generated: true }\n\nmodels:\n  Item:\n    label: Item\n    fields:\n      summary: { label: About }\n      kind: { values: { general: General, favorite: Favorite, archived: Archived } }\n      addedOn: { label: Added }\n\npages:\n  home:\n    hero:\n      title: Our collection\n      subtitle: The things we keep, where each one came from, and what we know about it. Most of them are still in use.\n      button: See everything\n    items:\n      title: In the collection\n    footer:\n      text: Made with care, one object at a time.\n  items:\n    subtitle: Everything we keep, newest first. Search by name or by what we wrote about it.\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: minimal\n\npages:\n  home:\n    theme: { preset: playful }         # the public page warmer than the tool behind it\n    sections:\n      items: { layout: grid, columns: 3, band: muted }   # the items' pictures, titled, on the muted band\n","smithable.yml":"smithable: 0.1\n\n# The neutral starter: things and what we know about them (dogs, tools, recipes, players,\n# jobs). A first build from a description adapts it when no other starter fits.\napp:\n  name: Our Collection\n  description: A place to keep and show a collection of items.\n  timezone: Europe/Mariehamn\n\nmodels:\n  Item:\n    description: One thing in the collection.\n    fields:\n      name: string!\n      summary: text\n      kind: general | favorite | archived      # the first value is the default\n      link: url\n      addedOn: date! = TODAY()\n\npages:\n  home:\n    route: /\n    landing:\n      hero: { button: items }\n      items: { records: Item }\n      footer:\n  items:\n    crud: Item\n    search: [name, summary]\n    filters: [kind]\n\nnavigation: [items]\n"},
  "status": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]\n  selfSignUp: false                # only people invited from the team page\n\ndefaultAccess: shared              # the team sees and writes everything\n\nroles:\n  admin: all\n  staff:\n    description: Writes incidents and their updates.\n    pages: [overview, incidents, updates, maintenance]   # the components and the team are the administrators'\n    create: all\n    write: all                       # any of the team moves any incident on\n\ndefaultRole: staff\nadmins: [ops@northwind.example]\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home, history]           # the status page and the incident history\n  read:\n    - Component\n    # Every state an incident has today is public; one added later is not until it is named here.\n    - Incident: { where: { status: [investigating, identified, monitoring, resolved] } }\n    - IncidentUpdate\n    - Maintenance\n\n# What other programs may reach with a key made on the team page (a monitoring tool posting\n# incidents, say). A key acts with its role: listing is not granting.\napi:\n  models: [Component, Incident]\n  actions: [resolve]\n  assistants: true                 # the same as tools for AI assistants, at /mcp (no deleting)\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"# What visitors read. Derived from names when not given here.\nsmithableContent: 0.1\nlogo: { src: images/logo.webp, alt: A pulse line in a circle, generated: true }\n\nmodels:\n  IncidentUpdate: { label: Update }\n  Maintenance: { label: Planned maintenance }\n\npages:\n  home:\n    hero:\n      title: Northwind service status\n      subtitle: The state of the Northwind shop, the app and payments. The team updates this page while an incident is going on, and every incident stays in the history afterwards. Times are Åland time.\n      button: See past incidents\n    services: { title: Services }\n    uptime: { title: The last 90 days, text: \"One bar a day for each service: green when it worked all day, amber or red when an incident was going on. Work we announced ahead is listed under planned maintenance.\" }\n    open: { title: Going on now }\n    recent: { title: Recently resolved }\n    planned: { title: Planned maintenance }\n  history:\n    title: Incident history\n  overview:\n    title: Overview\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: minimal\n\npages:\n  home:\n    sections:\n      recent: { layout: list }         # the resolved incidents as quiet rows\n      planned: { band: muted }\n\ntones:\n  Component.status: { operational: success, degraded: warning, down: danger, maintenance: neutral }\n  Incident.status: { investigating: danger, identified: warning, monitoring: warning, resolved: success }\n  IncidentUpdate.status: { investigating: danger, identified: warning, monitoring: warning, resolved: success }\n","smithable.yml":"# A status page: what works, what is being fixed, and what is planned. Visitors read it; the\n# team, invited, writes incidents and their updates.\nsmithable: 0.1\n\napp:\n  name: Northwind Status\n  description: Is it working? The state of our services, live.\n  timezone: Europe/Mariehamn\n\nmodels:\n  Component:\n    fields:\n      name: string!\n      status: operational | degraded | down | maintenance\n      description: text\n      incidents: Incident[]\n      maintenances: Maintenance[]       # planned work on it, on its page\n  Incident:\n    fields:\n      title: string!\n      status: investigating | identified | monitoring | resolved\n      component: Component\n      detectedAt: datetime!\n      resolvedAt: datetime\n      summary: markdown\n      updates: IncidentUpdate[]\n  IncidentUpdate:\n    fields:\n      incident: Incident!\n      at: datetime!\n      status: investigating | identified | monitoring | resolved\n      message: text!\n  Maintenance:\n    fields:\n      title: string!\n      component: Component\n      startsAt: datetime!\n      endsAt: datetime!\n      description: text\n\nactions:\n  identified:\n    on: Incident\n    when: { status: investigating }\n    set: { status: identified }\n    add:\n      IncidentUpdate: { at: NOW(), status: identified, message: The cause is found and a fix is being worked on. }\n    intent: The cause is found; the incident moves to identified, with an update saying so.\n  monitoring:\n    on: Incident\n    when: { status: [investigating, identified] }\n    set: { status: monitoring }\n    add:\n      IncidentUpdate: { at: NOW(), status: monitoring, message: A fix is out. We are watching before we close this. }\n    intent: A fix is out; the incident is watched before it is closed, with an update saying so.\n  resolve:\n    on: Incident\n    when: { status: [investigating, identified, monitoring] }\n    set: { status: resolved, resolvedAt: NOW() }\n    add:\n      IncidentUpdate: { at: NOW(), status: resolved, message: This incident is resolved. }\n    intent: The incident is over, with an update saying so. The component's state stays what the team sets.\n\npages:\n  home:\n    route: /\n    landing:\n      hero: { button: history }\n      services: { records: Component }\n      uptime: { custom: Uptime }       # src/custom/sections/Uptime.tsx, the starter's own\n      open: { records: Incident, where: { status: [investigating, identified, monitoring] } }\n      recent: { records: Incident, where: { status: resolved }, limit: 5 }\n      planned: { records: Maintenance, limit: 3 }\n      footer: {}\n  history:\n    articles: { model: Incident, title: title, body: summary, date: detectedAt }\n  incidents:\n    crud: Incident\n    actions: [identified, monitoring, resolve]\n    filters: [status]\n  updates: { crud: IncidentUpdate }\n  components: { crud: Component }\n  maintenance: { crud: Maintenance }\n  overview:\n    dashboard:\n      open: { count: Incident, where: { status: [investigating, identified, monitoring] } }\n      perMonth: { count: Incident, by: detectedAt }\n      latest: { list: Incident, limit: 5 }\n  team: { users: manage }\n\nnavigation:\n  main: [overview, incidents, updates, maintenance, components, team]\n\nincoming:\n  # A chat tool's slash command (\"/incident Payments are slow\") opens an incident: the command's\n  # text comes as a form, signed with its time; the tool checks the address first with a challenge.\n  chatCommand:\n    create: Incident\n    set: { title: \"{text}\", status: investigating, detectedAt: NOW() }\n    body: form\n    signed: { sha256: \"v0:{timestamp}:{body}\", prefix: \"v0=\", timestamp: X-Slack-Request-Timestamp }\n    header: X-Slack-Signature\n    challenge: challenge\n    as: staff\n"},
  "support": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [email]\n  selfSignUp: false                # only agents invited from the team page\n\ndefaultAccess: shared              # every agent sees and answers every case\n\nroles:\n  admin: all\n  agent:\n    description: Answers the cases, takes them and passes them on.\n    pages: [cases]\n    create: all\n    write: all\n    actions: all\n\ndefaultRole: agent\nadmins: [support@harbour.example]\n\n# Ask, the assistant in the app, for everyone who signs in (setAssistant).\nassistant:\n  for: signed-in\n","smithable.content.yml":"# What people read. Derived from names when not given here.\nsmithableContent: 0.1\nlogo: { src: images/logo.webp, alt: A speech bubble, generated: true }\n\nmodels:\n  SupportCase: { label: Case }\n\npages:\n  cases:\n    title: Cases\n    subtitle: Every request that came in by mail, who has it and where it stands. Open a case to read its thread and answer the customer from there.\n\noutgoing:\n  caseReceived:\n    subject: We got your request\n    text: Thank you for writing to Harbour Support. Your request is now a case, and its number is in the subject of this mail. If you want to add something, answer this mail and keep the subject as it is; your answer goes to the same case. We read the support mail on weekdays from 8 to 17 and usually answer within one working day.\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: minimal\n\ntones:\n  SupportCase.status: { open: warning, inProgress: neutral, closed: success, reopened: danger }\n\npages:\n  cases:\n    table:\n      columns: [subject, status, priority, assignee]   # the messages' count comes after them\n    record:\n      lists: { messages: thread }    # a case's messages as a conversation with a reply box\n","smithable.yml":"smithable: 0.1\napp:\n  name: Harbour Support\n  description: Mail from customers, answered by the team.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  SupportCase:\n    fields:\n      subject: string!\n      customerEmail: { type: email!, locked: true }   # who wrote in; fixed once the case exists\n      status: open | inProgress | closed | reopened\n      priority: { type: int!, min: 1, max: 5, default: 3 }\n      assignee: { type: User, required: { status: [inProgress, closed] } }\n      body: text                                      # the first mail's text\n      attachments: files\n      messages: Message[]\n  Message:\n    fields:\n      content: text!\n      sender: agent | customer                        # the reply box writes as an agent\n      agent: { type: User, by: app, default: ME() }   # who answered, filled by the app\n      fromEmail: email                                # the customer's address on a mail that came in\n      attachments: files\n      supportCase: SupportCase!\n\npages:\n  cases:\n    crud: SupportCase\n    search: [subject, customerEmail]\n    filters: [status, priority, assignee]\n    sortable: [priority, createdAt]\n    actions: [assignToMe, assignTo, startWork, close, reopen]\n  team:\n    users: manage\n\nnavigation: [cases, team]\n\nactions:\n  assignToMe:\n    on: SupportCase\n    when: { assignee: not ME() }\n    set: { assignee: ME() }\n    intent: \"Take the case: you become its assignee.\"\n  assignTo:\n    on: SupportCase\n    set: { assignee: }\n    intent: Give the case to an agent, chosen from the team.\n  startWork:\n    on: SupportCase\n    when: { status: [open, reopened] }\n    set: { status: inProgress }\n    intent: \"Someone is working on the case now; it needs an assignee.\"\n  close:\n    on: SupportCase\n    when: { status: [open, inProgress, reopened] }\n    set: { status: closed }\n    intent: The customer has their answer.\n  reopen:\n    on: SupportCase\n    when: { status: closed }\n    set: { status: reopened }\n    intent: The case needs more work after all.\n\n# Mail to the support address becomes a case; an answer to one of its mails joins the case as a\n# message (docs/design/mail-threads.md). The address and its secret are settings of the app.\nincoming:\n  support:\n    mail: true\n    create: SupportCase\n    fields: { from: customerEmail, subject: subject, body: body, attachments: attachments }\n    set: { status: open }\n    reply:\n      create: Message\n      fields: { from: fromEmail, body: content, attachments: attachments }\n      set: { sender: customer }\n\noutgoing:\n  caseReceived:\n    when: SupportCase created\n    to: mail\n    recipient: customerEmail\n  replySent:\n    when: Message created\n    where: { sender: agent }\n    to: mail\n    recipient: supportCase.customerEmail\n"},
};

export const STARTER_CODE: Record<string, Record<string, string>> = {
  "api": {},
  "barbers": {},
  "booking": {},
  "crm": {"src/custom/actions/schedule-follow-ups.test.ts":"// Tests for planning follow-ups (schedule-follow-ups.ts): custom logic needs its own tests.\nimport { eq } from \"drizzle-orm\";\nimport { describe, expect, test } from \"vitest\";\nimport { db } from \"#/db\";\nimport { customers, followUps } from \"#/db/schema\";\nimport { scheduleFollowUps } from \"./schedule-follow-ups\";\n\ndescribe(\"planning follow-ups\", () => {\n  test(\"the first is due today, each next one so many days later\", async () => {\n    const customer = db.insert(customers).values({ name: \"Follow Oy\" }).returning().get();\n    const { created } = await scheduleFollowUps(\n      { customer: customer.id, count: 3, everyDays: 7 },\n      null,\n    );\n    expect(created).toBe(3);\n    const due = db\n      .select()\n      .from(followUps)\n      .where(eq(followUps.customerId, customer.id))\n      .all()\n      .map((f) => f.dueOn)\n      .sort();\n    const day = (n: number) => new Date(Date.now() + n * 86_400_000).toISOString().slice(0, 10);\n    expect(due).toEqual([day(0), day(7), day(14)]);\n  });\n\n  test(\"at least one, at most a year of weeks\", async () => {\n    const customer = db.insert(customers).values({ name: \"None Oy\" }).returning().get();\n    await expect(\n      scheduleFollowUps({ customer: customer.id, count: 0, everyDays: 7 }, null),\n    ).rejects.toThrow(\"between 1 and 52\");\n  });\n});\n","src/custom/actions/schedule-follow-ups.ts":"// Your implementation of the \"scheduleFollowUps\" action in smithable.yml. Smithable created this file\n// once and never changes it. The input and output types are generated from the spec, so a change\n// to the action's input or output shows up here as a type error.\n// `viewer` is the signed-in user (null for a visitor). The records the input refers to are ones\n// they may read; the data functions in src/generated/*.server.ts check access for them.\nimport { db } from \"#/db\";\nimport { followUps } from \"#/db/schema\";\nimport type {\n  ScheduleFollowUpsInput,\n  ScheduleFollowUpsOutput,\n} from \"#/generated/actions/schedule-follow-ups\";\nimport type { Viewer } from \"#/kit/access\";\n\n/** A date as the app stores one, \"2026-10-29\", so many days after another. */\nfunction daysAfter(start: Date, days: number): string {\n  const day = new Date(start);\n  day.setUTCDate(day.getUTCDate() + days);\n  return day.toISOString().slice(0, 10);\n}\n\n/**\n * Plan a series of follow-up notes for a customer, one every so many days.\n *\n * Rules (from smithable.yml):\n * - The first note is due today; each next one everyDays later.\n */\nexport async function scheduleFollowUps(\n  { customer, count, everyDays }: ScheduleFollowUpsInput,\n  viewer: Viewer | null,\n): Promise<ScheduleFollowUpsOutput> {\n  if (count < 1 || count > 52) throw new Error(\"Plan between 1 and 52 follow-ups at a time.\");\n  if (everyDays < 1) throw new Error(\"Follow-ups are at least a day apart.\");\n  // Only the roles the auth file names may run this (smithable.yml); the generated action checks that first.\n  const today = new Date();\n  // All at once or not at all.\n  db.transaction((tx) => {\n    for (let i = 0; i < count; i++)\n      tx.insert(followUps)\n        .values({\n          customerId: customer,\n          dueOn: daysAfter(today, i * everyDays),\n          ownerId: viewer?.id,\n        })\n        .run();\n  });\n  return { created: count };\n}\n"},
  "invoicing": {},
  "kiosk": {},
  "marketplace": {},
  "records": {},
  "status": {"src/custom/sections/Uptime.tsx":"// The status starter's section of its own (docs/spec/v0.1.md, Pages and sections of your own):\n// the last 90 days of each service, one bar a day, and the share of the time it was up. The\n// data comes from the generated data functions, so visitors see what they may read.\nimport { createServerFn } from \"@tanstack/react-start\";\nimport { useEffect, useState } from \"react\";\nimport { componentData } from \"#/generated/component.server\";\nimport type { CustomSectionProps } from \"#/generated/custom\";\nimport { incidentData } from \"#/generated/incident.server\";\nimport { Section } from \"#/kit/Landing\";\nimport { currentViewer } from \"#/lib/viewer.server\";\nimport { uptime } from \"./uptime\";\n\nconst DAYS = 90;\n\n/** The services and when each one's incidents began and ended. */\nconst loadUptime = createServerFn().handler(async () => {\n  const viewer = await currentViewer();\n  const [components, incidents] = await Promise.all([\n    componentData.list(viewer),\n    incidentData.list(viewer),\n  ]);\n  return {\n    now: Date.now(),\n    services: components.map((c) => ({\n      id: c.id,\n      name: c.name,\n      outages: incidents\n        .filter((i) => i.componentId === c.id)\n        .map((i) => ({ from: i.detectedAt.getTime(), to: i.resolvedAt?.getTime() ?? null })),\n    })),\n  };\n});\n\nexport function Uptime({ name, texts, title, text }: CustomSectionProps) {\n  const [data, setData] = useState<Awaited<ReturnType<typeof loadUptime>>>();\n  useEffect(() => {\n    loadUptime().then(setData, () => undefined);\n  }, []);\n  return (\n    <Section id={name} texts={texts} title={title} text={text}>\n      {data ? (\n        <ul className=\"space-y-6\">\n          {data.services.map((service) => {\n            const { days, up } = uptime(service.outages, data.now, DAYS);\n            const percent = `${(Math.floor(up * 10_000) / 100).toFixed(2)}%`;\n            return (\n              <li key={service.id}>\n                <div className=\"mb-2 flex justify-between gap-4 text-sm\">\n                  <span className=\"font-medium\">{service.name}</span>\n                  <span className=\"text-muted-foreground\">{percent} up</span>\n                </div>\n                <div\n                  role=\"img\"\n                  aria-label={`${service.name}: ${percent} up over the last ${DAYS} days`}\n                  className=\"flex h-8 gap-px\"\n                >\n                  {days.map((day) => (\n                    <span\n                      key={day.date}\n                      title={`${day.date}: ${day.minutes ? `${day.minutes} minutes down` : \"no incidents\"}`}\n                      className={`flex-1 rounded-sm ${day.minutes === 0 ? \"bg-success\" : day.minutes < 60 ? \"bg-warning\" : \"bg-destructive\"}`}\n                    />\n                  ))}\n                </div>\n                <div className=\"mt-1 flex justify-between text-xs text-muted-foreground\">\n                  <span>{DAYS} days ago</span>\n                  <span>Today</span>\n                </div>\n              </li>\n            );\n          })}\n        </ul>\n      ) : (\n        <p className=\"text-sm text-muted-foreground\">Loading…</p>\n      )}\n    </Section>\n  );\n}\n","src/custom/sections/uptime.test.ts":"import { expect, test } from \"vitest\";\nimport { uptime } from \"./uptime\";\n\nconst now = Date.parse(\"2026-10-03T12:00:00Z\");\nconst at = (iso: string) => Date.parse(`${iso}Z`);\n\ntest(\"a day without incidents is all up; an incident counts on the days it lasted\", () => {\n  const { days, up } = uptime(\n    [{ from: at(\"2026-10-01T23:30:00\"), to: at(\"2026-10-02T00:30:00\") }],\n    now,\n    3,\n  );\n  expect(days).toEqual([\n    { date: \"2026-10-01\", minutes: 30 },\n    { date: \"2026-10-02\", minutes: 30 },\n    { date: \"2026-10-03\", minutes: 0 },\n  ]);\n  // An hour down in two and a half days.\n  expect(up).toBeCloseTo(1 - 1 / 60, 4);\n});\n\ntest(\"overlapping incidents count once, an open one runs to now, older ones are left out\", () => {\n  const { days } = uptime(\n    [\n      { from: at(\"2026-10-03T10:00:00\"), to: at(\"2026-10-03T11:00:00\") },\n      { from: at(\"2026-10-03T10:30:00\"), to: null },\n      { from: at(\"2026-06-01T10:00:00\"), to: at(\"2026-06-01T11:00:00\") },\n    ],\n    now,\n    3,\n  );\n  expect(days.map((d) => d.minutes)).toEqual([0, 0, 120]);\n});\n\ntest(\"a day with less than a minute down is not shown as all up\", () => {\n  const { days } = uptime(\n    [{ from: at(\"2026-10-03T10:00:00\"), to: at(\"2026-10-03T10:00:20\") }],\n    now,\n    1,\n  );\n  expect(days[0]?.minutes).toBe(1);\n});\n","src/custom/sections/uptime.ts":"// How long a service was down, day by day: the incidents' times (detected to resolved, or to now\n// while open), overlaps counted once. Days are UTC days.\nconst DAY = 86_400_000;\n\nexport interface Outage {\n  from: number;\n  /** Still open when null. */\n  to: number | null;\n}\n\n/** The last `days` days, oldest first, each with its minutes down, and the share of them up. */\nexport function uptime(outages: Outage[], now: number, days = 90) {\n  const start = Math.floor(now / DAY) * DAY - (days - 1) * DAY;\n  // Clipped to the period and merged, so two incidents at once count once.\n  const spans = outages\n    .map((o) => [Math.max(o.from, start), Math.min(o.to ?? now, now)] as const)\n    .filter(([from, to]) => to > from)\n    .sort((a, b) => a[0] - b[0]);\n  const merged: [number, number][] = [];\n  for (const [from, to] of spans) {\n    const last = merged.at(-1);\n    if (last && from <= last[1]) last[1] = Math.max(last[1], to);\n    else merged.push([from, to]);\n  }\n  const minutes = Array.from({ length: days }, () => 0);\n  let down = 0;\n  for (const [from, to] of merged) {\n    down += to - from;\n    for (let t = from; t < to; ) {\n      const day = Math.floor((t - start) / DAY);\n      const end = Math.min(to, start + (day + 1) * DAY);\n      minutes[day] = (minutes[day] ?? 0) + (end - t) / 60_000;\n      t = end;\n    }\n  }\n  return {\n    days: minutes.map((m, i) => ({\n      date: new Date(start + i * DAY).toISOString().slice(0, 10),\n      // Up: a day with any time down shows it, even under a minute.\n      minutes: Math.ceil(m),\n    })),\n    up: 1 - down / (now - start),\n  };\n}\n"},
  "support": {},
};

